            "stewardship",
            "livability",
            "dismantled"
        ];

        band9Terms.sort((a, b) => b.length - a.length);
        const escaped = band9Terms.map(t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
        const regex = new RegExp(`\\b(${escaped.join('|')})\\b`, 'gi');
        return out.replace(regex, '<mark class="lexical-highlight">$1</mark>');
