    function onSandboxInput() {
        const text = document.getElementById('essay-sandbox').value.trim();
        const words = text ? text.split(/\s+/).length : 0;
        document.getElementById('writing-word-count').innerText = `${words} words ${words >= 250 ? 'âœ“ (Task 2 Min Met)' : (words >= 150 ? 'âœ“ (Task 1 Min Met)' : '')}`;
    }

    function updateBandText(btnEl, masterAns, band) {
        const parent = btnEl.closest('.band-model-box');
        parent.querySelectorAll('.band-tab-btn').forEach(b => b.classList.remove('active'));
        btnEl.classList.add('active');

        const displayBox = parent.querySelector('.answer-display-box');
        if (band >= 8.5) {
            displayBox.innerHTML = highlightKeywords(masterAns);
        } else if (band >= 7.5) {
            displayBox.innerText = "I would like to share my perspective on this topic. Over the past couple of years, this has been an essential area of personal development. When facing this situation, I implemented structured approaches to resolve the core issues effectively. The outcome was highly favorable and provided valuable life lessons.";
        } else if (band >= 6.5) {
            displayBox.innerText = "I want to talk about this topic because it is important for me. A couple of years ago, I had a big challenge with my schedule. It was hard because I had many exams at the same time. But I made a study timetable and asked my friends for help. Finally I passed all my exams with good grades, so I was very happy.";
        } else {
            displayBox.innerText = "This happened to me some time ago. It was very difficult and I felt stressed. But my teacher helped me and I tried my best every day. So in the end everything was okay and I learned many good things.";
        }
    }

    /* -------------------------------------------------------------
       TAB 3: LOTTIE ANIMATION & RANDOM MATCHMAKER
    ------------------------------------------------------------- */
    let lottieAnimInstance = null;
    function initLottieCallAnimation() {
        // Animation handled by authentic Sonar/Radar rings in Stitch design
    }

    let mqttClient = null;
    let isSearchingRandom = false;
    let searchInterval = null;
    let activeCallChatTopic = null;
    let processedCallMsgIds = new Set();
    const MATCH_LOBBY_TOPIC = "ielts/speaking/match_lobby_v1";

    function subscribeCallSessionTopic(partnerId) {
        if (!mqttClient || !partnerId) return;
        const myId = getOrCreatePermanentId();
        activeCallChatTopic = "ielts/call_chat/" + [myId, partnerId].sort().join('_');
        try {
            mqttClient.subscribe(activeCallChatTopic);
        } catch(e) {}
    }

    function unsubscribeCallSessionTopic() {
        if (activeCallChatTopic && mqttClient) {
            try {
                mqttClient.unsubscribe(activeCallChatTopic);
            } catch(e) {}
            activeCallChatTopic = null;
        }
    }

    // Matchmaking queue state
    let callAttempting = null;
    let callAttemptTimer = null;
    const availablePeers = new Map();
    const candidateBlacklist = new Map();
    // Partners from just-ended calls: never auto-rematch with them during the cooldown window.
    const recentPartnerCooldown = new Map();
    const RECENT_PARTNER_COOLDOWN_MS = 10 * 60 * 1000;

    function markPartnerAsRecent(pid) {
        if (pid) recentPartnerCooldown.set(pid, Date.now());
    }

    function isRecentPartner(pid) {
        const t = recentPartnerCooldown.get(pid);
        if (!t) return false;
        if (Date.now() - t > RECENT_PARTNER_COOLDOWN_MS) {
            recentPartnerCooldown.delete(pid);
            return false;
        }
        return true;
    }

    function initMqttMatchmaking() {
        try {
            if (typeof mqtt === 'undefined') {
                setTimeout(initMqttMatchmaking, 300);
                return;
            }
            mqttClient = mqtt.connect("wss://broker.hivemq.com:8884/mqtt", {
                clientId: 'ielts_web_' + Math.random().toString(16).substring(2, 8),
                clean: true,
                keepalive: 30
            });

            mqttClient.on('connect', () => {
                const myId = getOrCreatePermanentId();
                mqttClient.subscribe(MATCH_LOBBY_TOPIC);
                mqttClient.subscribe('ielts/dm/' + myId);
                console.log("Web connected to global matchmaking lobby!");
                const callTab = document.getElementById('tab-call');
                if (callTab && callTab.style.display !== 'none' && !activeMediaCall) {
                    broadcastPresence('SEARCHING');
                    evaluateMatchmakingCandidates();
                }
            });

            mqttClient.on('message', (topic, payload) => {
                const myId = getOrCreatePermanentId();

                // 1. IN-CALL LIVE CHAT
                if (activeCallChatTopic && topic === activeCallChatTopic) {
                    try {
                        const data = JSON.parse(payload.toString());
                        if (data.senderId === myId) return;
                        if (data.msgId && processedCallMsgIds.has(data.msgId)) return;
                        if (data.msgId) processedCallMsgIds.add(data.msgId);

                        appendChatMessageToFeed(data.senderName || "Partner", data.text, data.time, false);

                        const sheet = document.getElementById('incall-chat-sheet');
                        if (!sheet.classList.contains('open')) {
                            incallUnreadCount++;
                            const badge = document.getElementById('call-unread-badge');
                            if (badge) badge.style.display = 'block';
                            showToast(`${data.senderName || "Partner"}: ${data.text.substring(0, 25)}...`);
                        }
                    } catch(e) {}
                    return;
                }

                // 2. MATCHMAKING CANDIDATE DISCOVERY
                if (topic === MATCH_LOBBY_TOPIC) {
                    try {
                        const msg = JSON.parse(payload.toString());
                        if (!msg.peerId || msg.peerId === myId) return;

                        if (msg.type === 'MATCH_CLAIM') {
                            if (msg.to === myId) {
                                console.log("Incoming match claim from", msg.from);
                                callAttempting = msg.from;
                                document.getElementById('call-status-heading').innerText = "Connecting with partner...";
                                if (callAttemptTimer) clearTimeout(callAttemptTimer);
                                callAttemptTimer = setTimeout(() => {
                                    if (callAttempting === msg.from && isSearchingRandom && !activeMediaCall) {
                                        console.warn("Claim timeout waiting for", msg.from);
                                        candidateBlacklist.set(msg.from, Date.now());
                                        callAttempting = null;
                                        document.getElementById('call-status-heading').innerText = "Searching for Speaking Partners";
                                        evaluateMatchmakingCandidates();
                                    }
                                }, 5000);
                            } else {
                                candidateBlacklist.set(msg.to, Date.now());
                            }
                            return;
                        }

                        const isBusy = (
                            msg.status === 'BUSY' || 
                            msg.status === 'IN_CALL' || 
                            msg.inCall === true || 
                            msg.status === 'OFF_CALL_PAGE' || 
                            msg.page === 'other' || 
                            msg.type === 'LEAVE_CALL_PAGE'
                        );

                        if (isBusy) {
                            availablePeers.delete(msg.peerId);
                            updateCandidateCountDisplay();
                            if (callAttempting === msg.peerId && !activeMediaCall) {
                                callAttempting = null;
                                if (callAttemptTimer) clearTimeout(callAttemptTimer);
                                evaluateMatchmakingCandidates();
                            }
                            return;
                        }

                        // Eligible candidate: must be on live call page, available/searching, and not in a call
                        const isEligible = (
                            (msg.status === 'AVAILABLE' || msg.status === 'SEARCHING' || msg.type === 'WAITING') &&
                            msg.inCall !== true &&
                            (msg.page === 'call' || !msg.page)
                        );

                        if (isEligible) {
                            availablePeers.set(msg.peerId, {
                                status: 'AVAILABLE',
                                peerId: msg.peerId,
                                page: 'call',
                                inCall: false,
                                name: msg.name || 'Candidate',
                                band: msg.targetBand || msg.band || 'Band 7.5',
                                country: msg.country || 'Global',
                                lastSeen: Date.now()
                            });
                            updateCandidateCountDisplay();
                            evaluateMatchmakingCandidates();
                        }
                    } catch (e) {}
                    return;
                }

                // 3. TAB 4 DIRECT 1-ON-1 CHAT
                if (topic === ('ielts/dm/' + myId)) {
                    try {
                        const data = JSON.parse(payload.toString());
                        const senderId = data.senderId;
                        const senderName = data.senderName || ("Partner (" + senderId.slice(-4) + ")");

                        let contacts = getSavedContacts();
                        let contact = contacts.find(c => c.id === senderId);
                        if (!contact) {
                            contact = {
                                id: senderId,
                                name: senderName,
                                country: data.senderCountry || "Global",
                                targetBand: data.senderBand || "Band 7.5",
                                lastMsg: data.text,
                                lastTime: data.time
                            };
                            contacts.unshift(contact);
                        } else {
                            contact.lastMsg = data.text;
                            contact.lastTime = data.time;
                        }
                        saveContactsList(contacts);

                        saveChatMessage(senderId, {
                            sender: senderName,
                            text: data.text,
                            time: data.time,
                            isSent: false
                        });

                        if (activeDirectContact && activeDirectContact.id === senderId) {
                            const feed = document.getElementById('direct-chat-feed');
                            if (feed) {
                                if (feed.querySelector('div[style*="text-align:center"]')) {
                                    feed.innerHTML = '';
                                }
                                const bubble = document.createElement('div');
                                bubble.className = 'chat-bubble received';
                                bubble.innerHTML = `
                                    <div style="font-size:11px; font-weight:700; color:var(--primary); margin-bottom:2px;">${escapeHtml(senderName)}</div>
                                    <div>${escapeHtml(data.text)}</div>
                                    <div style="font-size:10px; color:var(--on-surface-variant); text-align:right; margin-top:2px;">${data.time}</div>
                                `;
                                feed.appendChild(bubble);
                                feed.scrollTop = feed.scrollHeight;
                            }
                        } else {
                            showToast(`New message from ${senderName}: ${data.text.substring(0, 28)}...`);
                        }
                        renderDirectContacts();
                    } catch(e) {}
                    return;
                }
            });
        } catch (err) {}
    }

    function updateCandidateCountDisplay() {
        const el = document.getElementById('call-candidate-count-text');
        if (!el) return;
        const count = availablePeers.size;
        if (count > 0) {
            el.innerHTML = `<strong style='color:var(--on-surface); font-weight:700;'>${count} candidate${count > 1 ? 's' : ''}</strong> currently on this page`;
        } else {
            el.innerHTML = `<strong style='color:var(--on-surface); font-weight:700;'>Searching for partners</strong> on this page...`;
        }
    }

    function enterCallPage() {
        startRandomMatchmaking();
    }

    function leaveCallPage() {
        stopRandomMatchmaking();
        broadcastPresence('OFF_CALL_PAGE');
        availablePeers.clear();
        updateCandidateCountDisplay();
    }

    function startRandomMatchmaking() {
        if (activeMediaCall) return;
        const callTab = document.getElementById('tab-call');
        if (!callTab || callTab.style.display === 'none') return;

        isSearchingRandom = true;
        callAttempting = null;
        showTopLoader();
        document.getElementById('call-status-heading').innerText = "Searching for Speaking Partners";
        document.getElementById('call-partner-meta').innerHTML = 'Matching by Target Band <span style="font-weight:700; color:var(--primary);">7.0 – 8.5</span> &amp; Cambridge Cue Cards';
        document.getElementById('searching-controls-row').style.display = 'flex';
        document.getElementById('call-in-progress-controls').style.display = 'none';
        const connActions = document.getElementById('call-connected-actions');
        if (connActions) connActions.style.display = 'none';
        document.getElementById('call-timer-display').style.display = 'none';
        document.getElementById('call-waveform-box').style.display = 'none';

        broadcastPresence('SEARCHING');
        evaluateMatchmakingCandidates();

        if (searchInterval) clearInterval(searchInterval);
        searchInterval = setInterval(() => {
            const callTab = document.getElementById('tab-call');
            const isOnCall = callTab && callTab.style.display !== 'none';
            if (isOnCall && isSearchingRandom && !activeMediaCall) {
                broadcastPresence('SEARCHING');
                evaluateMatchmakingCandidates();
            }
        }, 2000);
    }

    function evaluateMatchmakingCandidates() {
        const callTab = document.getElementById('tab-call');
        const isOnCall = callTab && callTab.style.display !== 'none';
        if (!isOnCall || !isSearchingRandom || activeMediaCall || callAttempting || !peerInstance || peerInstance.destroyed) return;

        const now = Date.now();
        const myId = getOrCreatePermanentId();

        // Prune expired peers (> 6s)
        for (const [pid, data] of availablePeers.entries()) {
            if (now - data.lastSeen > 6000 || data.inCall === true || data.status === 'BUSY') {
                availablePeers.delete(pid);
            }
        }
        // Prune blacklist (> 8s)
        for (const [pid, time] of candidateBlacklist.entries()) {
            if (now - time > 8000) {
                candidateBlacklist.delete(pid);
            }
        }

        updateCandidateCountDisplay();

        // Deterministic pairing: smaller ID initiates call to larger ID
        const candidates = [];
        for (const [pid, data] of availablePeers.entries()) {
            if (pid !== myId && !candidateBlacklist.has(pid) && !isRecentPartner(pid) && data.status === 'AVAILABLE') {
                if (myId < pid) {
                    candidates.push({ peerId: pid, ...data });
                }
            }
        }

        if (candidates.length === 0) return;

        // Sort by most recently active
        candidates.sort((a, b) => b.lastSeen - a.lastSeen);
        const target = candidates[0];

        console.log("Matchmaking candidate selected on Live Call page:", target.peerId);
        callAttempting = target.peerId;
        document.getElementById('call-status-heading').innerText = "Connecting with partner...";

        // Broadcast claim to lobby so other peers do not collide
        if (mqttClient && mqttClient.connected) {
            try {
                mqttClient.publish(MATCH_LOBBY_TOPIC, JSON.stringify({
                    type: 'MATCH_CLAIM',
                    from: myId,
                    to: target.peerId,
                    timestamp: now
                }));
            } catch(e) {}
        }

        startOutgoingCallTo(target.peerId, target.name, target.band, target.country);

        // Safety timeout: If not connected in 5s, blacklist and return to search
        if (callAttemptTimer) clearTimeout(callAttemptTimer);
        callAttemptTimer = setTimeout(() => {
            if (callAttempting === target.peerId && isSearchingRandom && !activeMediaCall) {
                console.warn("Call attempt to " + target.peerId + " timed out. Returning to search.");
                candidateBlacklist.set(target.peerId, Date.now());
                callAttempting = null;
                if (activeMediaCall) {
                    try { activeMediaCall.close(); } catch(e){}
                    activeMediaCall = null;
                }
                document.getElementById('call-status-heading').innerText = "Searching for Speaking Partners";
                evaluateMatchmakingCandidates();
            }
        }, 5000);
    }

    function broadcastPresence(status = 'SEARCHING') {
        if (!mqttClient || !mqttClient.connected) return;
        const myId = getOrCreatePermanentId();
        const now = Date.now();
        const callTab = document.getElementById('tab-call');
        const isOnCall = callTab && callTab.style.display !== 'none';
        const inCall = !!activeMediaCall;
        const page = isOnCall ? 'call' : 'other';
        const finalStatus = inCall ? 'IN_CALL' : (isOnCall ? (isSearchingRandom ? 'SEARCHING' : 'READY') : 'OFF_CALL_PAGE');

        try {
            mqttClient.publish(MATCH_LOBBY_TOPIC, JSON.stringify({
                type: 'PRESENCE',
                status: finalStatus,
                page: page,
                inCall: inCall,
                peerId: myId,
                name: userProfile.name || 'Candidate',
                targetBand: userProfile.targetBand || 'Band 7.5',
                country: userProfile.country || 'Global',
                timestamp: now
            }));
            if (finalStatus === 'SEARCHING') {
                mqttClient.publish(MATCH_LOBBY_TOPIC, JSON.stringify({
                    type: 'WAITING',
                    status: 'AVAILABLE',
                    page: 'call',
                    inCall: false,
                    peerId: myId,
                    name: userProfile.name || 'Candidate',
                    targetBand: userProfile.targetBand || 'Band 7.5',
                    country: userProfile.country || 'Global',
                    timestamp: now
                }));
            }
        } catch (e) {}
    }

    function broadcastWaiting() {
        broadcastPresence('SEARCHING');
    }

    function stopRandomMatchmaking() {
        isSearchingRandom = false;
        callAttempting = null;
        if (callAttemptTimer) {
            clearTimeout(callAttemptTimer);
            callAttemptTimer = null;
        }
        hideTopLoader();
        if (searchInterval) {
            clearInterval(searchInterval);
            searchInterval = null;
        }
    }

    function cancelMatchmaking() {
        leaveCallPage();
        hideTopLoader();
        document.getElementById('call-status-heading').innerText = "Matchmaking Paused";
        document.getElementById('call-partner-meta').innerText = "Tap Find Random Partner when ready to connect";
        showToast("Matchmaking paused");
    }

    function nextRandomPartner() {
        hangupActiveCall(true);
        showToast("Finding next practice partner...");
        setTimeout(() => {
            startRandomMatchmaking();
        }, 300);
    }

    /* -------------------------------------------------------------
       WEBRTC AUDIO ENGINE & IN-CALL MESSAGING
    ------------------------------------------------------------- */
    let peerInstance = null;
    let activeMediaCall = null;
    let activeDataConn = null;
    let localStream = null;
    let callTimerInterval = null;
    let secondsElapsed = 0;
    let incallUnreadCount = 0;

    let activePartnerId = null;
    let activePartnerName = null;
    let activePartnerBand = null;
    let activePartnerCountry = null;

    let carouselYear = 2026;
    let carouselQuestionsList = [];
    let currentCarouselIndex = 0;

    function createSilentAudioStream() {
        try {
            const ctx = new (window.AudioContext || window.webkitAudioContext)();
            const gain = ctx.createGain();
            gain.gain.setValueAtTime(0, ctx.currentTime);
            const dst = ctx.createMediaStreamDestination();
            gain.connect(dst);
            const track = dst.stream.getAudioTracks()[0];
            if (track) track.enabled = false;
            return dst.stream;
        } catch(e) {
            console.warn("Failed to create silent stream fallback:", e);
            return null;
        }
    }

    // Voice-optimized Audio Constraints with standard W3C echo cancellation, noise suppression, and AGC disabled to prevent screeching feedback loops
    const CLEAN_AUDIO_CONSTRAINTS = {
        audio: {
            echoCancellation: true,
            noiseSuppression: true,
            autoGainControl: false,
            googEchoCancellation: true,
            googEchoCancellation2: true,
            googNoiseSuppression: true,
            googHighpassFilter: true,
            googAutoGainControl: false,
            googAutoGainControl2: false
        },
        video: false
    };

    const FALLBACK_AUDIO_CONSTRAINTS = {
        audio: {
            echoCancellation: true,
            noiseSuppression: true,
            autoGainControl: false
        },
        video: false
    };

    // Opus SDP Optimizer: Enforces mono, discontinuous transmission (DTX to eliminate background noise during pauses), and forward error correction
    function optimizeOpusSdp(sdp) {
        if (!sdp) return sdp;
        return sdp.replace(/a=fmtp:(\d+)(.*)/g, (line, pt, params) => {
            if (sdp.includes(`a=rtpmap:${pt} opus/48000`)) {
                let p = params.trim();
                if (!p.includes('usedtx=')) p += ';usedtx=1';
                if (!p.includes('useinbandfec=')) p += ';useinbandfec=1';
                if (!p.includes('stereo=')) p += ';stereo=0';
                if (!p.includes('sprop-stereo=')) p += ';sprop-stereo=0';
                if (!p.includes('maxaveragebitrate=')) p += ';maxaveragebitrate=32000';
                if (!p.includes('cbr=')) p += ';cbr=0';
                return `a=fmtp:${pt} ${p}`;
            }
            return line;
        });
    }

    if (window.RTCPeerConnection) {
        const origCreateOffer = RTCPeerConnection.prototype.createOffer;
        RTCPeerConnection.prototype.createOffer = function() {
            const ret = origCreateOffer.apply(this, arguments);
            if (ret && typeof ret.then === 'function') {
                return ret.then(offer => {
                    if (offer && offer.sdp) {
                        try {
                            offer.sdp = optimizeOpusSdp(offer.sdp);
                        } catch(e){}
                    }
                    return offer;
                });
            }
            return ret;
        };

        const origCreateAnswer = RTCPeerConnection.prototype.createAnswer;
        RTCPeerConnection.prototype.createAnswer = function() {
            const ret = origCreateAnswer.apply(this, arguments);
            if (ret && typeof ret.then === 'function') {
                return ret.then(answer => {
                    if (answer && answer.sdp) {
                        try {
                            answer.sdp = optimizeOpusSdp(answer.sdp);
                        } catch(e){}
                    }
                    return answer;
                });
            }
            return ret;
        };

        const origSetLocalDescription = RTCPeerConnection.prototype.setLocalDescription;
        RTCPeerConnection.prototype.setLocalDescription = function(desc) {
            if (desc && desc.sdp) {
                try {
                    const modified = {
                        type: desc.type,
                        sdp: optimizeOpusSdp(desc.sdp)
                    };
                    return origSetLocalDescription.call(this, modified);
                } catch(e) {
                    console.warn("SDP local optimization failed:", e);
                }
            }
            return origSetLocalDescription.apply(this, arguments);
        };

        const origSetRemoteDescription = RTCPeerConnection.prototype.setRemoteDescription;
        RTCPeerConnection.prototype.setRemoteDescription = function(desc) {
            if (desc && desc.sdp) {
                try {
                    const modified = {
                        type: desc.type,
                        sdp: optimizeOpusSdp(desc.sdp)
                    };
                    return origSetRemoteDescription.call(this, modified);
                } catch(e) {
                    console.warn("SDP remote optimization failed:", e);
                }
            }
            return origSetRemoteDescription.apply(this, arguments);
        };
    }

    function processRemoteStream(remoteStream) {
        const remoteAudio = document.getElementById('remoteAudio');
        if (!remoteAudio) return;
        try {
            // CRITICAL: WebRTC native Acoustic Echo Cancellation (AEC3) requires the raw
            // MediaStream directly attached to <audio>. Pumping through WebAudio destination
            // breaks browser far-end reference queues, creating severe screeching acoustic loops.
            remoteAudio.srcObject = remoteStream;
            remoteAudio.volume = 1.0;
            const slider = document.getElementById('partner-vol-slider');
            if (slider) slider.value = '1.0';
            const label = document.getElementById('partner-vol-label');
            if (label) label.innerText = '100%';
            remoteAudio.setAttribute('playsinline', 'true');
            const playPromise = remoteAudio.play();
            if (playPromise !== undefined) {
                playPromise.catch(err => {
                    console.log("Audio autoplay deferred pending user interaction:", err);
                    const unlock = () => {
                        remoteAudio.play().catch(e => console.log("Unlock retry failed:", e));
                        window.removeEventListener('click', unlock);
                        window.removeEventListener('touchstart', unlock);
                    };
                    window.addEventListener('click', unlock, { once: true });
                    window.addEventListener('touchstart', unlock, { once: true });
                });
            }
        } catch (err) {
            console.warn("Direct stream assignment failed:", err);
        }
    }

    function cleanupAudioProcessing() {
        const remoteAudio = document.getElementById('remoteAudio');
        if (remoteAudio) {
            try {
                remoteAudio.pause();
                remoteAudio.srcObject = null;
            } catch(e){}
        }
        const slider = document.getElementById('partner-vol-slider');
        if (slider) slider.value = '1.0';
        const label = document.getElementById('partner-vol-label');
        if (label) label.innerText = '100%';
    }

    function setPartnerVolume(val) {
        const audioEl = document.getElementById('remoteAudio');
        if (audioEl) {
            audioEl.volume = parseFloat(val);
        }
        const label = document.getElementById('partner-vol-label');
        if (label) {
            label.innerText = Math.round(parseFloat(val) * 100) + '%';
        }
    }

    // Sender-side noise gate: the mic (already AEC/NS processed by getUserMedia) is passed through a
    // gate so that when the local user stops talking, digital silence is transmitted. This lets Opus DTX
    // idle cleanly instead of sending residual mic noise / noise-suppressor artifacts (heard as a loud
    // hiss by the partner right after speech ends). Only the LOCAL mic is processed here; the remote
    // stream is still attached raw to <audio id="remoteAudio"> (native AEC/NS preserved).
    let rawLocalStream = null;
    let gateTimer = null;
    let gateCtx = null;

    async function buildGatedStream(rawStream) {
        try {
            const AC = window.AudioContext || window.webkitAudioContext;
            if (!AC) return rawStream;
            const ctx = new AC();
            if (ctx.state !== 'running') {
                try {
                    await Promise.race([ctx.resume(), new Promise(r => setTimeout(r, 600))]);
                } catch(e) {}
            }
            // If the context cannot run (e.g. iOS autoplay policy) a gated track would be silent -> use raw mic.
            if (ctx.state !== 'running') {
                try { ctx.close(); } catch(e) {}
                return rawStream;
            }
            const src = ctx.createMediaStreamSource(rawStream);
            const hp = ctx.createBiquadFilter();
            hp.type = 'highpass';
            hp.frequency.value = 90;
            const analyser = ctx.createAnalyser();
            analyser.fftSize = 1024;
            const lookahead = ctx.createDelay(0.1);
            lookahead.delayTime.value = 0.03;
            const gate = ctx.createGain();
            gate.gain.value = 0;
            const dst = ctx.createMediaStreamDestination();

            src.connect(hp);
            hp.connect(analyser);
            hp.connect(lookahead);
            lookahead.connect(gate);
            gate.connect(dst);

            const buf = new Float32Array(analyser.fftSize);
            const OPEN_RMS = 0.006;   // ~ -44 dBFS
            const CLOSE_RMS = 0.004;  // ~ -48 dBFS
            const HOLD_MS = 500;
            let isOpen = false;
            let lastLoud = 0;

            if (gateTimer) clearInterval(gateTimer);
            if (gateCtx && gateCtx !== ctx) { try { gateCtx.close(); } catch(e) {} }
            gateCtx = ctx;

            gateTimer = setInterval(() => {
                if (ctx.state === 'suspended') { try { ctx.resume(); } catch(e) {} }
                // Background tabs throttle timers; keep the gate open so speech is never clipped.
                if (document.hidden) {
                    if (!isOpen) { gate.gain.setTargetAtTime(1, ctx.currentTime, 0.01); isOpen = true; }
                    return;
                }
                analyser.getFloatTimeDomainData(buf);
                let sum = 0;
                for (let i = 0; i < buf.length; i++) sum += buf[i] * buf[i];
                const rms = Math.sqrt(sum / buf.length);
                const now = performance.now();
                if (rms >= (isOpen ? CLOSE_RMS : OPEN_RMS)) lastLoud = now;
                const shouldOpen = (now - lastLoud) < HOLD_MS;
                if (shouldOpen !== isOpen) {
                    isOpen = shouldOpen;
                    gate.gain.setTargetAtTime(isOpen ? 1 : 0, ctx.currentTime, isOpen ? 0.008 : 0.08);
                }
            }, 20);

            if (!dst.stream.getAudioTracks()[0]) return rawStream;
            // The mute button / loopback guard operate on this stream's track, i.e. what is actually sent.
            return dst.stream;
        } catch (e) {
            console.warn("Noise gate setup failed, using raw mic:", e);
            return rawStream;
        }
    }

    async function ensureLocalStream() {
        if (localStream && localStream.getAudioTracks().length > 0 && rawLocalStream) {
            const rawTrack = rawLocalStream.getAudioTracks()[0];
            if (rawTrack && rawTrack.readyState === 'live') {
                return localStream;
            }
        }
        try {
            if (typeof navigator !== 'undefined' && navigator.audioSession) {
                try {
                    navigator.audioSession.type = 'play-and-record';
                } catch(e) {}
            }
            if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
                try {
                    rawLocalStream = await navigator.mediaDevices.getUserMedia(CLEAN_AUDIO_CONSTRAINTS);
                } catch (e1) {
                    console.warn("Clean constraints unsupported, falling back to basic audio:", e1);
                    try {
                        rawLocalStream = await navigator.mediaDevices.getUserMedia(FALLBACK_AUDIO_CONSTRAINTS);
                    } catch (e2) {
                        rawLocalStream = await navigator.mediaDevices.getUserMedia({ audio: true, video: false });
                    }
                }
                if (rawLocalStream) {
                    rawLocalStream.getAudioTracks().forEach(track => {
                        track.enabled = true;
                    });
                    localStream = await buildGatedStream(rawLocalStream);
                    localStream.getAudioTracks().forEach(track => {
                        track.enabled = true;
                    });
                    return localStream;
                }
            }
        } catch (err) {
            document.getElementById('call-status-heading').innerText = "Microphone Permission Required";
            showToast("Microphone access is required for audio calling");
            localStream = createSilentAudioStream();
            return localStream;
        }
        localStream = createSilentAudioStream();
        return localStream;
    }

    async function initWebRtcEngine() {
        if (typeof Peer === 'undefined') {
            setTimeout(initWebRtcEngine, 300);
            return;
        }
        try {
            const permanentId = getOrCreatePermanentId();
            updateIdDisplays();

            peerInstance = new Peer(permanentId, {
                config: {
                    iceServers: [
                        { urls: 'stun:stun.l.google.com:19302' },
                        { urls: 'stun:stun1.l.google.com:19302' },
                        { urls: 'stun:global.stun.twilio.com:3478' }
                    ]
                }
            });

            peerInstance.on('open', (id) => {
                updateIdDisplays();
                initMqttMatchmaking();
                const callTab = document.getElementById('tab-call');
                if (callTab && callTab.style.display !== 'none' && !activeMediaCall) {
                    startRandomMatchmaking();
                }
            });

            peerInstance.on('call', async (call) => {
                console.log("Incoming call on Web from:", call.peer);
                if (activeMediaCall) {
                    console.log("Already in call, rejecting duplicate call from", call.peer);
                    try { call.close(); } catch(e){}
                    return;
                }
                const callTab = document.getElementById('tab-call');
                if (!callTab || callTab.style.display === 'none') {
                    console.log("Rejecting incoming call because user is not on Live Call page:", call.peer);
                    try { call.close(); } catch(e){}
                    return;
                }
                if (isRecentPartner(call.peer)) {
                    console.log("Rejecting incoming call from previous partner (cooldown):", call.peer);
                    try { call.close(); } catch(e){}
                    return;
                }
                stopRandomMatchmaking();
                activePartnerId = call.peer;
                activePartnerName = "Partner (" + call.peer.slice(-4) + ")";
                activePartnerBand = activePartnerBand || "Band 7.5";
                activeMediaCall = call;
                callAttempting = call.peer;
                if (callAttemptTimer) clearTimeout(callAttemptTimer);
                subscribeCallSessionTopic(call.peer);
                const stream = await ensureLocalStream();
                call.answer(stream);
                bindMediaCallStreams(call);
            });

            peerInstance.on('connection', (conn) => {
                bindDataConnection(conn);
            });

            peerInstance.on('error', (err) => {
                console.warn("PeerJS error:", err);
                if (isSearchingRandom && (err.type === 'peer-unavailable' || err.type === 'network' || err.type === 'server-error')) {
                    if (callAttempting) {
                        candidateBlacklist.set(callAttempting, Date.now());
                        callAttempting = null;
                    }
                    if (activeMediaCall) {
                        try { activeMediaCall.close(); } catch(e){}
                        activeMediaCall = null;
                    }
                    if (callAttemptTimer) clearTimeout(callAttemptTimer);
                    document.getElementById('call-status-heading').innerText = "Searching for Speaking Partners";
                    setTimeout(evaluateMatchmakingCandidates, 1200);
                    return;
                }
            });

        } catch (err) {}
    }

    function toggleIdControls() {
        const panel = document.getElementById('id-controls-panel');
        if (!panel) return;
        const isHidden = (panel.style.display === 'none' || panel.style.display === '');
        panel.style.display = isHidden ? 'block' : 'none';

        const headerKey = document.getElementById('header-key-icon');
        if (headerKey) {
            headerKey.innerText = isHidden ? 'vpn_key_off' : 'vpn_key';
        }
        const btn = document.getElementById('call-by-id-btn');
        if (btn) {
            btn.classList.toggle('active', isHidden);
        }
    }

    function toggleIdControlsFromHeader() {
        const targetTab = document.getElementById('tab-call');
        if (!targetTab || targetTab.style.display === 'none') {
            switchTab('call');
        }
        toggleIdControls();
    }

    function startOutgoingCallManual() {
        const partnerId = document.getElementById('partner-id-input').value.trim();
        if (!partnerId) return alert("Please enter partner's Call ID");
        startOutgoingCallTo(partnerId, "Partner", "Band 7.5", "Global");
    }

    async function startOutgoingCallTo(targetId, name, band, country) {
        if (!peerInstance) return alert("WebRTC engine not ready. Check connection.");
        const stream = await ensureLocalStream();
        if (!stream) return;
        stopRandomMatchmaking();

        activePartnerId = targetId;
        activePartnerName = name || ("Partner (" + targetId.slice(-4) + ")");
        activePartnerBand = band || "Band 7.5";
        activePartnerCountry = country || "Global";

        document.getElementById('call-status-heading').innerText = "Connecting with partner...";
        document.getElementById('call-partner-meta').innerText = `${activePartnerName} (${activePartnerBand})`;

        const call = peerInstance.call(targetId, stream);
        activeMediaCall = call;
        bindMediaCallStreams(call);

        const conn = peerInstance.connect(targetId);
        bindDataConnection(conn);

        subscribeCallSessionTopic(targetId);
    }

    // Same-device / Dual-Tab Loopback Guard
    const deviceCallChannel = (typeof BroadcastChannel !== 'undefined') ? new BroadcastChannel('ielts_device_call_sync') : null;

    function notifyDeviceCallStart(partnerId) {
        if (deviceCallChannel) {
            try {
                deviceCallChannel.postMessage({
                    type: 'CALL_CONNECTED',
                    myId: getOrCreatePermanentId(),
                    partnerId: partnerId
                });
            } catch(e){}
        }
    }

    if (deviceCallChannel) {
        deviceCallChannel.onmessage = (evt) => {
            if (evt.data && evt.data.type === 'CALL_CONNECTED') {
                const myId = getOrCreatePermanentId();
                if (evt.data.myId === activePartnerId || evt.data.partnerId === myId) {
                    console.log("Dual-tab loopback detected on the same computer!");
                    // Auto-mute answering tab to prevent physical speaker-mic feedback howl
                    if (localStream && localStream.getAudioTracks().length > 0) {
                        const track = localStream.getAudioTracks()[0];
                        track.enabled = false;
                        const btn = document.getElementById('call-mute-btn');
                        if (btn) {
                            btn.classList.add('muted');
                            const icon = btn.querySelector('.material-symbols-outlined');
                            if (icon) icon.innerText = 'mic_off';
                        }
                    }
                    showToast("🎧 Same-device test: Mic muted to prevent speaker squeal. Use headphones!");
                }
            }
        };
    }

    function bindMediaCallStreams(call) {
        subscribeCallSessionTopic(call.peer);
        call.on('stream', (remoteStream) => {
            console.log("Remote audio stream active from:", call.peer);
            notifyDeviceCallStart(call.peer);
            if (callAttemptTimer) clearTimeout(callAttemptTimer);
            callAttempting = null;
            stopRandomMatchmaking();
            broadcastPresence('IN_CALL');

            processRemoteStream(remoteStream);
            document.getElementById('call-status-heading').innerText = "Connected with Practice Partner";
            const currentBand = activePartnerBand || "Band 7.5";
            document.getElementById('call-partner-meta').innerText = activePartnerName ? `${activePartnerName} • ${currentBand}` : `Speaking Partner • ${currentBand}`;
            document.getElementById('id-controls-panel').style.display = 'none';
            document.getElementById('searching-controls-row').style.display = 'none';
            document.getElementById('call-in-progress-controls').style.display = 'flex';
            const volRow = document.getElementById('call-volume-row');
            if (volRow) volRow.style.display = 'flex';
            document.getElementById('call-timer-display').style.display = 'block';
            document.getElementById('call-waveform-box').style.display = 'flex';

            selectCallYearFromSidebar(activeSpeakingYear);
            startCallTimer();
        });

        call.on('error', (err) => {
            console.error("Active call error:", err);
            cleanupAudioProcessing();
            if (isSearchingRandom) {
                if (callAttempting) {
                    candidateBlacklist.set(callAttempting, Date.now());
                    callAttempting = null;
                }
                if (callAttemptTimer) clearTimeout(callAttemptTimer);
                activeMediaCall = null;
                setTimeout(evaluateMatchmakingCandidates, 1200);
                return;
            }
            hangupActiveCall(false);
        });

        call.on('close', () => {
            cleanupAudioProcessing();
            hangupActiveCall(false);
        });
    }

    function bindDataConnection(conn) {
        activeDataConn = conn;
        conn.on('data', (data) => {
            if (data && data.type === 'HANGUP') {
                console.log("Received HANGUP via WebRTC DataConnection");
                hangupActiveCall(false);
                showToast("Partner disconnected");
                return;
            }
            if (data && data.type === 'CHAT_MSG') {
                if (data.msgId && processedCallMsgIds.has(data.msgId)) return;
                if (data.msgId) processedCallMsgIds.add(data.msgId);

                appendChatMessageToFeed(data.sender, data.text, data.time, false);

                const sheet = document.getElementById('incall-chat-sheet');
                if (!sheet.classList.contains('open')) {
                    incallUnreadCount++;
                    const badge = document.getElementById('call-unread-badge');
                    if (badge) badge.style.display = 'block';
                    showToast(`${data.sender}: ${data.text.substring(0, 25)}...`);
                }
            }
        });

        conn.on('close', () => {
            console.log("WebRTC DataConnection closed by remote partner");
            if (activeMediaCall) {
                hangupActiveCall(false);
                showToast("Partner ended the call");
            }
        });
    }

    function toggleCallMute() {
        if (localStream && localStream.getAudioTracks().length > 0) {
            const track = localStream.getAudioTracks()[0];
            track.enabled = !track.enabled;
            const btn = document.getElementById('call-mute-btn');
            if (btn) {
                btn.classList.toggle('muted', !track.enabled);
                const icon = btn.querySelector('.material-symbols-outlined');
                if (icon) icon.innerText = track.enabled ? 'mic' : 'mic_off';
            }
            showToast(track.enabled ? "Microphone Unmuted" : "Microphone Muted");
        }
    }

    function openInCallChatSheet() {
        document.getElementById('incall-chat-sheet').classList.add('open');
        incallUnreadCount = 0;
        document.getElementById('call-unread-badge').style.display = 'none';
    }

    function closeInCallChatSheet() {
        document.getElementById('incall-chat-sheet').classList.remove('open');
    }

    function sendInCallMessage() {
        const input = document.getElementById('incall-msg-input');
        const txt = input.value.trim();
        if (!txt) return;

        const timeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        const senderName = userProfile.name || 'You';
        const myId = getOrCreatePermanentId();
        const msgId = 'callmsg_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6);
        processedCallMsgIds.add(msgId);

        appendChatMessageToFeed(senderName, txt, timeStr, true);
        input.value = '';

        if (activeDataConn && activeDataConn.open) {
            try {
                activeDataConn.send({
                    msgId: msgId,
                    type: 'CHAT_MSG',
                    sender: senderName,
                    text: txt,
                    time: timeStr
                });
            } catch(e) {}
        }

        if (mqttClient && mqttClient.connected && activeCallChatTopic) {
            try {
                mqttClient.publish(activeCallChatTopic, JSON.stringify({
                    msgId: msgId,
                    senderId: myId,
                    senderName: senderName,
                    text: txt,
                    time: timeStr
                }));
            } catch(e) {}
        }
    }

    function appendChatMessageToFeed(sender, text, time, isSent) {
        const feed = document.getElementById('incall-chat-feed');
        const bubble = document.createElement('div');
        bubble.className = `chat-bubble ${isSent ? 'sent' : 'received'}`;
        bubble.innerHTML = `
            ${!isSent ? `<div style="font-size:11px; font-weight:700; color:var(--primary); margin-bottom:2px;">${sender}</div>` : ''}
            <div>${escapeHtml(text)}</div>
            <div style="font-size:10px; opacity:0.8; text-align:right; margin-top:2px;">${time}</div>
        `;
        feed.appendChild(bubble);
        feed.scrollTop = feed.scrollHeight;
    }

    function sendHangupSignal() {
        const myId = getOrCreatePermanentId();
        const payload = {
            type: 'HANGUP',
            senderId: myId,
            timestamp: Date.now()
        };
        if (activeDataConn && activeDataConn.open) {
            try {
                activeDataConn.send(payload);
            } catch(e) {}
        }
        if (mqttClient && mqttClient.connected && activeCallChatTopic) {
            try {
                mqttClient.publish(activeCallChatTopic, JSON.stringify(payload));
            } catch(e) {}
        }
    }

    function hangupActiveCall(shouldBroadcast = true) {
        // Remember who we just talked to so matchmaking never reconnects us with them right away.
        if (activeMediaCall) {
            markPartnerAsRecent(activePartnerId || activeMediaCall.peer);
        }
        if (shouldBroadcast) {
            sendHangupSignal();
        }
        cleanupAudioProcessing();
        if (activeMediaCall) {
            try { activeMediaCall.close(); } catch(e) {}
            activeMediaCall = null;
        }
        if (activeDataConn) {
            try { activeDataConn.close(); } catch(e) {}
            activeDataConn = null;
        }
        callAttempting = null;
        if (callAttemptTimer) {
            clearTimeout(callAttemptTimer);
            callAttemptTimer = null;
        }
        unsubscribeCallSessionTopic();
        processedCallMsgIds.clear();
        clearInterval(callTimerInterval);
        document.getElementById('call-status-heading').innerText = "Call Ended";
        document.getElementById('call-partner-meta').innerText = "Ready for next practice partner";
        document.getElementById('call-in-progress-controls').style.display = 'none';
        const volRow = document.getElementById('call-volume-row');
        if (volRow) volRow.style.display = 'none';
        document.getElementById('call-timer-display').style.display = 'none';
        document.getElementById('call-waveform-box').style.display = 'none';
        document.getElementById('searching-controls-row').style.display = 'flex';
        document.getElementById('incall-carousel-section').style.display = 'none';
        const idPanel = document.getElementById('id-controls-panel');
        if (idPanel) idPanel.style.display = 'none';
        const headerKey = document.getElementById('header-key-icon');
        if (headerKey) headerKey.innerText = 'vpn_key';
        const idBtn = document.getElementById('call-by-id-btn');
        if (idBtn) idBtn.classList.remove('active');
        document.getElementById('incall-chat-sheet').classList.remove('open');
        secondsElapsed = 0;

        // Automatically resume matchmaking if user is on the Live Call page
        setTimeout(() => {
            const callTab = document.getElementById('tab-call');
            if (callTab && callTab.style.display !== 'none' && !activeMediaCall) {
                startRandomMatchmaking();
            } else {
                leaveCallPage();
            }
        }, 600);
    }

    function startCallTimer() {
        clearInterval(callTimerInterval);
        secondsElapsed = 0;
        callTimerInterval = setInterval(() => {
            secondsElapsed++;
            const m = String(Math.floor(secondsElapsed / 60)).padStart(2, '0');
            const s = String(secondsElapsed % 60).padStart(2, '0');
            document.getElementById('call-timer-display').innerText = `${m}:${s}`;
        }, 1000);
    }

    function saveCurrentPartnerToContacts() {
        if (!activePartnerId) return showToast("No active partner to save");
        const contacts = getSavedContacts();
        if (!contacts.find(c => c.id === activePartnerId)) {
            contacts.unshift({
                id: activePartnerId,
                name: activePartnerName || ("Partner " + activePartnerId.slice(-4)),
                country: activePartnerCountry || "Global",
                targetBand: activePartnerBand || "Band 7.5",
                lastMsg: "Connected via Live Match",
                lastTime: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            });
            saveContactsList(contacts);
            showToast("Partner saved to Direct Messages!");
            renderDirectContacts();
        } else {
            showToast("Partner is already in your Contacts!");
        }
    }

    /* -------------------------------------------------------------
       IN-CALL QUESTION CAROUSEL & DRAWER
    ------------------------------------------------------------- */
    function toggleSidebarDrawer() {
        document.getElementById('incall-sidebar-drawer').classList.toggle('open');
    }

    function renderInCallSidebarYears() {
        const list = document.getElementById('sidebar-years-list');
        list.innerHTML = allYears.map(yr => `
            <div class="filter-pill" style="display:block; text-align:left; margin-bottom:4px;" onclick="selectCallYearFromSidebar(${yr})">Year ${yr} (Cam ${getCambridgeBook(yr)})</div>
        `).join('');
    }

    function selectCallYearFromSidebar(year) {
        carouselYear = year;
        const paper = getSpeakingPaperData(year);
        carouselQuestionsList = [];
        paper.sets.forEach(set => {
            set.questions.forEach(q => {
                carouselQuestionsList.push({
                    title: `${set.setTitle} â€¢ ${q.qLabel}`,
                    prompt: q.prompt,
                    bullets: q.bullets
                });
            });
        });

        currentCarouselIndex = 0;
        document.getElementById('incall-sidebar-drawer').classList.remove('open');
        document.getElementById('incall-carousel-section').style.display = 'block';
        renderCarouselCard();
    }

    function renderCarouselCard() {
        if (!carouselQuestionsList.length) return;
        const q = carouselQuestionsList[currentCarouselIndex];
        document.getElementById('carousel-year-title').innerText = `${carouselYear} (${currentCarouselIndex + 1}/${carouselQuestionsList.length}): ${q.title}`;
        document.getElementById('carousel-card-body').innerHTML = `
            <p style="font-weight:700; margin-bottom:6px; color:var(--primary);">${q.prompt.replace(/\n/g, '<br/>')}</p>
        `;
    }

    function carouselPrev() {
        if (currentCarouselIndex > 0) {
            currentCarouselIndex--;
            renderCarouselCard();
        }
    }

    function carouselNext() {
        if (currentCarouselIndex < carouselQuestionsList.length - 1) {
            currentCarouselIndex++;
            renderCarouselCard();
        }
    }

    /* -------------------------------------------------------------
       LIVE CALL: HEADER TOGGLE + SPEAKING QUESTION SET BROWSER
    ------------------------------------------------------------- */
    let callQsetYear = null;
    let callQsetIndex = 0;

    function toggleCallInfoPanel() {
        const tab = document.getElementById('tab-call');
        if (!tab) return;
        const hidden = tab.classList.toggle('call-info-hidden');
        const btn = document.getElementById('header-call-toggle-btn');
        if (btn) btn.classList.toggle('active', hidden);
        if (hidden) renderCallQsetPanel();
    }

    function renderCallQsetPanel() {
        if (callQsetYear === null) callQsetYear = activeSpeakingYear || allYears[0];
        document.getElementById('call-qset-year-value').innerText = `${callQsetYear} (Cam ${getCambridgeBook(callQsetYear)})`;

        const paper = getSpeakingPaperData(callQsetYear);
        if (!paper || !paper.sets || !paper.sets.length) {
            document.getElementById('call-qset-set-value').innerText = '—';
            document.getElementById('call-qset-topic').innerText = '';
            document.getElementById('call-qset-questions').innerHTML = '<p style="font-size:12px; color:var(--on-surface-variant);">No question sets available for this year.</p>';
            return;
        }
        if (callQsetIndex >= paper.sets.length) callQsetIndex = 0;

        const currentSet = paper.sets[callQsetIndex];
        document.getElementById('call-qset-set-value').innerText = currentSet.setTitle;
        document.getElementById('call-qset-topic').innerText = currentSet.topicTheme || '';
        // Same cards as the Speaking tab: question + Band 9.0 model answer
        document.getElementById('call-qset-questions').innerHTML = buildSpeakingQuestionCards(currentSet);
    }

    function openCallQsetPicker(kind) {
        const list = document.getElementById('call-qset-picker-list');
        const title = document.getElementById('call-qset-picker-title');
        if (kind === 'year') {
            title.innerText = 'Select Year';
            list.innerHTML = allYears.map(yr => `
                <div class="qset-picker-item ${yr === callQsetYear ? 'selected' : ''}" onclick="selectCallQsetYear(${yr})">
                    <span>${yr}</span><span style="font-size:12px; opacity:0.8;">Cambridge ${getCambridgeBook(yr)}</span>
                </div>`).join('');
        } else {
            title.innerText = 'Select Question Set';
            const paper = getSpeakingPaperData(callQsetYear);
            const sets = (paper && paper.sets) ? paper.sets : [];
            list.innerHTML = sets.map((s, idx) => `
                <div class="qset-picker-item ${idx === callQsetIndex ? 'selected' : ''}" onclick="selectCallQsetSet(${idx})">
                    <span>${s.setTitle}</span>
                </div>`).join('');
        }
        document.getElementById('call-qset-picker').classList.add('open');
        // Scroll the current value into view, like a birthday year wheel
        const sel = list.querySelector('.selected');
        if (sel) list.scrollTop = Math.max(0, sel.offsetTop - list.clientHeight / 2 + sel.clientHeight / 2);
    }

    function closeCallQsetPicker() {
        document.getElementById('call-qset-picker').classList.remove('open');
    }

    function selectCallQsetYear(year) {
        callQsetYear = year;
        callQsetIndex = 0;
        closeCallQsetPicker();
        renderCallQsetPanel();
    }

    function selectCallQsetSet(idx) {
        callQsetIndex = idx;
        closeCallQsetPicker();
        renderCallQsetPanel();
    }

    /* -------------------------------------------------------------
       TAB 4: DIRECT 1-ON-1 CHAT (100% PERSISTENT, ZERO DUMMY CHATS)
    ------------------------------------------------------------- */
    let activeDirectContact = null;

    function getSavedContacts() {
        try {
            return JSON.parse(localStorage.getItem('ielts_direct_contacts')) || [];
        } catch (e) {
            return [];
        }
    }

    function saveContactsList(list) {
        localStorage.setItem('ielts_direct_contacts', JSON.stringify(list));
    }

    function getChatMessages(contactId) {
        try {
            return JSON.parse(localStorage.getItem('ielts_chat_msgs_' + contactId)) || [];
        } catch (e) {
            return [];
        }
    }

    function saveChatMessage(contactId, msg) {
        const msgs = getChatMessages(contactId);
        msgs.push(msg);
        localStorage.setItem('ielts_chat_msgs_' + contactId, JSON.stringify(msgs));

        const contacts = getSavedContacts();
        const idx = contacts.findIndex(c => c.id === contactId);
        if (idx >= 0) {
            contacts[idx].lastMsg = msg.text;
            contacts[idx].lastTime = msg.time;
            saveContactsList(contacts);
        }
    }

    function renderDirectContacts() {
        const contacts = getSavedContacts();
        const container = document.getElementById('direct-contacts-list');
        const emptyState = document.getElementById('direct-empty-state');

        if (!contacts || contacts.length === 0) {
            container.innerHTML = '';
            emptyState.style.display = 'block';
            return;
        }

        emptyState.style.display = 'none';
        container.innerHTML = contacts.map(c => `
            <div class="chat-contact-card" onclick="openDirectChat('${c.id}')">
                <div class="chat-avatar-disc">${(c.name || 'P').charAt(0).toUpperCase()}</div>
                <div style="flex:1;">
                    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:2px;">
                        <span style="font-weight:800; font-size:14px; color:var(--primary);">${escapeHtml(c.name)}</span>
                        <span style="font-size:11px; color:var(--on-surface-variant); font-weight:600;">${c.lastTime || ''}</span>
                    </div>
                    <div style="font-size:11px; color:var(--secondary); font-weight:700; margin-bottom:2px;">ID: ${c.id} â€¢ ${c.targetBand || 'Band 7.5'}</div>
                    <div style="font-size:12px; color:var(--on-surface-variant); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:240px;">${escapeHtml(c.lastMsg || 'Tap to chat')}</div>
                </div>
            </div>
        `).join('');
    }

    function openDirectChat(contactId) {
        const contacts = getSavedContacts();
        const contact = contacts.find(c => c.id === contactId);
        if (!contact) return;
        activeDirectContact = contact;

        document.getElementById('direct-contacts-view').style.display = 'none';
        document.getElementById('direct-chat-window').classList.add('active');
        document.getElementById('chat-window-name').innerText = contact.name;
        document.getElementById('chat-window-status').innerText = `ID: ${contact.id} â€¢ ${contact.targetBand || 'Band 7.5'}`;

        const feed = document.getElementById('direct-chat-feed');
        feed.innerHTML = '';

        const messages = getChatMessages(contactId);
        if (messages.length === 0) {
            feed.innerHTML = `<div style="text-align:center; padding:30px; color:var(--on-surface-variant); font-size:12px;">No messages yet. Send a message to start practicing!</div>`;
        } else {
            messages.forEach(m => {
                const bubble = document.createElement('div');
                bubble.className = `chat-bubble ${m.isSent ? 'sent' : 'received'}`;
                bubble.innerHTML = `
                    ${!m.isSent ? `<div style="font-size:11px; font-weight:700; color:var(--primary); margin-bottom:2px;">${escapeHtml(contact.name)}</div>` : ''}
                    <div>${escapeHtml(m.text)}</div>
                    <div style="font-size:10px; opacity:0.8; text-align:right; margin-top:2px;">${m.time}</div>
                `;
                feed.appendChild(bubble);
            });
            feed.scrollTop = feed.scrollHeight;
        }
    }

    function closeDirectChatWindow() {
        document.getElementById('direct-chat-window').classList.remove('active');
        document.getElementById('direct-contacts-view').style.display = 'block';
        activeDirectContact = null;
        renderDirectContacts();
    }

    function sendDirectMsg() {
        if (!activeDirectContact) return;
        const input = document.getElementById('direct-msg-input');
        const txt = input.value.trim();
        if (!txt) return;

        const timeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        const myId = getOrCreatePermanentId();
        const myName = userProfile.name || 'Practice Partner';

        const newMsg = {
            sender: "Me",
            text: txt,
            time: timeStr,
            isSent: true
        };

        saveChatMessage(activeDirectContact.id, newMsg);

        const feed = document.getElementById('direct-chat-feed');
        if (feed.querySelector('div[style*="text-align:center"]')) {
            feed.innerHTML = '';
        }
        const bubble = document.createElement('div');
        bubble.className = 'chat-bubble sent';
        bubble.innerHTML = `
            <div>${escapeHtml(txt)}</div>
            <div style="font-size:10px; opacity:0.8; text-align:right; margin-top:2px;">${timeStr}</div>
        `;
        feed.appendChild(bubble);
        feed.scrollTop = feed.scrollHeight;
        input.value = '';

        if (mqttClient && mqttClient.connected) {
            try {
                mqttClient.publish('ielts/dm/' + activeDirectContact.id, JSON.stringify({
                    senderId: myId,
                    senderName: myName,
                    senderBand: userProfile.targetBand || 'Band 7.5',
                    senderCountry: userProfile.country || 'Global',
                    text: txt,
                    time: timeStr,
                    timestamp: Date.now()
                }));
            } catch(e) {}
        }
    }

    function deleteCurrentChat() {
        if (!activeDirectContact) return;
        if (!confirm(`Delete conversation with ${activeDirectContact.name}?`)) return;

        let contacts = getSavedContacts().filter(c => c.id !== activeDirectContact.id);
        saveContactsList(contacts);
        localStorage.removeItem('ielts_chat_msgs_' + activeDirectContact.id);
        showToast("Conversation deleted");
        closeDirectChatWindow();
    }

    function callCurrentChatPartner() {
        if (!activeDirectContact) return;
        const partnerId = activeDirectContact.id;
        const name = activeDirectContact.name;
        const band = activeDirectContact.targetBand;
        switchTab('call');
        startOutgoingCallTo(partnerId, name, band, "Global");
    }

    function openAddPartnerModal() {
        document.getElementById('add-partner-modal').classList.add('open');
        document.getElementById('new-partner-id-input').value = '';
        document.getElementById('new-partner-name-input').value = '';
    }

    function closeAddPartnerModal() {
        document.getElementById('add-partner-modal').classList.remove('open');
    }

    function saveNewPartner() {
        const idInput = document.getElementById('new-partner-id-input').value.trim();
        if (!idInput) return alert("Please enter partner's Permanent IELTS ID");

        const nameInput = document.getElementById('new-partner-name-input').value.trim() || idInput;
        const bandInput = document.getElementById('new-partner-band-input').value.trim() || "Band 7.5";

        const contacts = getSavedContacts();
        const existing = contacts.find(c => c.id === idInput);
        if (!existing) {
            contacts.unshift({
                id: idInput,
                name: nameInput,
                targetBand: bandInput,
                lastMsg: "Added to contacts",
                lastTime: "Just now"
            });
            saveContactsList(contacts);
        }
        closeAddPartnerModal();
        renderDirectContacts();
        openDirectChat(idInput);
    }

    /* -------------------------------------------------------------
       TAB 5: CANDIDATE PROFILE
    ------------------------------------------------------------- */
    function setGender(g) {
        userProfile.gender = g;
        document.querySelectorAll('#gender-chips-container .filter-pill').forEach(btn => {
            btn.classList.toggle('active', btn.innerText === g);
        });
    }

    function setTargetBand(b) {
        userProfile.targetBand = b;
        document.querySelectorAll('#band-chips-container .filter-pill').forEach(btn => {
            btn.classList.toggle('active', btn.innerText === b);
        });
        const num = b.replace('Band ', '');
        const el = document.getElementById('header-band-badge');
        if (el) el.innerText = num;
        const elBento = document.getElementById('prof-bento-band');
        if (elBento) elBento.innerText = num;
    }

    function toggleEditProfileForm() {
        const f = document.getElementById('prof-form-card');
        if (f) {
            f.scrollIntoView({ behavior: 'smooth' });
        }
    }

    function saveCandidateProfile() {
        userProfile.name = document.getElementById('prof-name-input').value.trim() || 'Jhan Student';
        userProfile.age = document.getElementById('prof-age-input').value.trim() || '23';
        userProfile.country = document.getElementById('prof-country-input').value.trim() || 'Vietnam';

        localStorage.setItem('ielts_profile_config', JSON.stringify(userProfile));
        document.getElementById('prof-display-name').innerText = userProfile.name;
        document.getElementById('prof-display-country').innerText = `${userProfile.country} â€¢ Target ${userProfile.targetBand}`;
        showToast("Profile Settings Saved Successfully!");
    }

    function loadUserProfile() {
        const saved = localStorage.getItem('ielts_profile_config');
        if (saved) {
            try {
                userProfile = JSON.parse(saved);
                document.getElementById('prof-name-input').value = userProfile.name || 'Jhan Student';
                document.getElementById('prof-age-input').value = userProfile.age || '23';
                document.getElementById('prof-country-input').value = userProfile.country || 'Vietnam';
                document.getElementById('prof-display-name').innerText = userProfile.name || 'Jhan Student';
                document.getElementById('prof-display-country').innerText = `${userProfile.country || 'Vietnam'} â€¢ Target ${userProfile.targetBand || 'Band 7.5'}`;
                setGender(userProfile.gender || 'Male');
                setTargetBand(userProfile.targetBand || 'Band 7.5');
            } catch (e) {}
        }
    }

    /* -------------------------------------------------------------
       UTILITIES & DOM READY INITIALIZER
    ------------------------------------------------------------- */
    function showToast(msg) {
        const t = document.getElementById('global-toast');
        t.innerText = msg;
        t.style.display = 'block';
        setTimeout(() => { t.style.display = 'none'; }, 2800);
    }

    function copyTextToClipboard(text) {
        navigator.clipboard.writeText(text).then(() => {
            showToast("Copied to clipboard!");
        });
    }

    function escapeHtml(str) {
        if (!str) return "";
        return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    }

    function escapeJs(str) {
        if (!str) return "";
        return str.replace(/'/g, "\\'").replace(/\n/g, "\\n");
    }

    function initApp() {
        hideTopLoader();
        loadUserProfile();
        updateIdDisplays();
        renderDirectContacts();
        renderInCallSidebarYears();
        setTimeout(initWebRtcEngine, 200);

        window.addEventListener('beforeunload', () => {
            leaveCallPage();
        });
        window.addEventListener('pagehide', () => {
            leaveCallPage();
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initApp);
    } else {
        initApp();
    }
    //
